          "SAL non presentati in tempo — ogni settimana di ritardo nella presentazione del SAL è una settimana in meno di liquidità. Molte imprese non hanno un sistema per tracciare quando presentare e incassare i SAL.",
          "Termini di pagamento fornitori più stretti degli incassi dai clienti — se paghi i fornitori a 30 giorni ma incassi a 90, stai finanziando il cliente con il tuo denaro.",
          "Anticipi non richiesti — la maggior parte dei contratti privati ammette un anticipo del 20-30% all'avvio dei lavori. Molte imprese non lo richiedono sistematicamente.",
