          "Costi di cantieri aperti non monitorati — un cantiere che va avanti senza controllo dei costi consuma liquidità in eccesso rispetto al preventivo, spesso senza che il titolare se ne accorga.",
          "Nessuna previsione finanziaria — senza una proiezione a 30-60-90 giorni di incassi e uscite, la crisi di cassa arriva sempre come sorpresa.",
