        body: "Il Piano Nazionale di Ripresa e Resilienza ha stanziato oltre 191 miliardi di euro per trasformare l'Italia entro il 2026. Per le imprese edili, il PNRR rappresenta la più grande opportunità commerciale degli ultimi decenni — ma anche la più impegnativa dal punto di vista organizzativo. Scadenze rigide, rendicontazione digitale obbligatoria, SAL asseverati, DURC impeccabile: le imprese che non hanno processi organizzativi solidi rischiano di perdere i pagamenti anche dopo aver completato i lavori. In questa guida ti spieghiamo cosa c'è ancora disponibile nel 2025-2026, come qualificarti e come organizzarti per non perdere neanche un euro.",
