        heading: "I Rischi Tipici nei Cantieri PNRR e Come Evitarli",
        body: "I cantieri PNRR presentano rischi specifici che non si trovano negli appalti ordinari. Il rischio principale è la perdita del pagamento per non-conformità documentale: se la rendicontazione non è completa o non rispetta i formati richiesti, il pagamento SAL viene sospeso finché non vengono prodotti i documenti mancanti. Questo può durare settimane e creare crisi di liquidità gravi. Il secondo rischio è lo scorrimento dei cronoprogrammi: se il tuo subappaltatore ritarda, se arrivano materiali difettosi o se le autorizzazioni tardano, il milestone europeo potrebbe non essere rispettato — e la stazione appaltante potrebbe rivalersi sull'impresa esecutrice con penali pesanti. Il terzo rischio è il subappalto non autorizzato: nei cantieri PNRR il controllo sul subappalto è molto stringente. Ogni subappaltatore deve essere autorizzato preventivamente dalla stazione appaltante, con verifica del DURC e dei requisiti.",
