        heading: "Il Piano di Implementazione: Come Passare al Nuovo Gestionale Senza Caos",
        body: "Una volta scelto il software, l'implementazione è la fase più critica. Le imprese che falliscono nella digitalizzazione spesso hanno scelto il software giusto ma lo hanno implementato nel modo sbagliato. Il piano di implementazione vincente ha 4 fasi. Fase 1 (settimana 1-2): configurazione del sistema con i dati della tua impresa (tariffe operai, listini fornitori, template commesse). Fase 2 (settimana 3-4): migrazione dei dati attivi (cantieri aperti, clienti principali, fornitori ricorrenti). Fase 3 (mese 2): avvio parallelo — usi sia il vecchio sistema che il nuovo per un mese, confrontando i dati. Fase 4 (mese 3): dismissione del vecchio sistema, il team lavora esclusivamente sul nuovo. La chiave è non fare tutto insieme: inizia con la funzionalità più critica (es. gestione margini) e aggiungi le altre gradualmente.",
